SINA_SMART["viro1-herpesviruses"] = {"lecture":"viro1-herpesviruses","title":"Herpesviruses","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"viro1-herpesviruses:e0","text":"Herpesviruses: large enveloped dsDNA viruses; nuclear replication.","topic":"General features","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-herpesviruses:e1","text":"All establish lifelong latency with reactivation.","topic":"General features","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-herpesviruses:e2","text":"Latent DNA is episomal, not integrated; no replication → escapes drugs.","topic":"General features","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-herpesviruses:e3","text":"α (HSV, VZV): sensory ganglia; β (CMV): glands, blood; γ (EBV): lymphocytes.","topic":"Transmission","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-herpesviruses:e4","text":"HSV-1: oral, eye, brain. HSV-2: genital, neonatal.","topic":"HSV-1 and HSV-2","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-herpesviruses:e5","text":"HSV encephalitis: temporal, necrotising; emergency (aciclovir).","topic":"HSV-1 and HSV-2","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-herpesviruses:e6","text":"VZV: chickenpox, then shingles in a dermatome.","topic":"VZV and EBV","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-herpesviruses:e7","text":"EBV: mononucleosis; Burkitt lymphoma, nasopharyngeal carcinoma.","topic":"VZV and EBV","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-herpesviruses:e8","text":"Diagnosis by PCR on fresh lesions.","topic":"Diagnosis, treatment, prevention","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-herpesviruses:e9","text":"Aciclovir/valaciclovir; ganciclovir for CMV; varicella and shingles vaccines.","topic":"Diagnosis, treatment, prevention","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1uhnl6a":"a","1w88sxr":"a","vs9bcm":"a","17zi26n":"a","9p2tna":"a","1z4gfy":"a","1a1cf2m":"a","x4b06x":"a","32lhf6":"a","1gqsa7k":"a","16uwh5d":"a","1mnt4ys":"a","nziyrq":"a","18062nv":"a","t2l5y0":"a","1afcl4y":"a"},"mapCounts":{"verified":0,"auto":16,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"viro1-herpesviruses:e0":{"s":0,"u":["Herpesviruses: large enveloped dsDNA viruses; nuclear replication.","Herpesviruses are large double-stranded DNA viruses (150-230 kb), 120-200 nm, with an icosahedral capsid and an envelope ; replication is entirely nuclear (immediate-early activator proteins, early enzymes including DNA polymerase, rolling-circle DNA replication, late structural proteins, budding through the nuclear membrane)."],"dp":[]},"viro1-herpesviruses:e1":{"s":0,"u":["All establish lifelong latency with reactivation."],"dp":[]},"viro1-herpesviruses:e2":{"s":0,"u":["Latent DNA is episomal, not integrated; no replication → escapes drugs.","Latent DNA is episomal (not integrated), with no replication or protein expression, so it escapes the immune system and antivirals.","Herpesviruses are large double-stranded DNA viruses (150-230 kb), 120-200 nm, with an icosahedral capsid and an envelope ; replication is entirely nuclear (immediate-early activator proteins, early enzymes including DNA polymerase, rolling-circle DNA replication, late structural proteins, budding through the nuclear membrane)."],"dp":[]},"viro1-herpesviruses:e3":{"s":1,"u":["α (HSV, VZV): sensory ganglia; β (CMV): glands, blood; γ (EBV): lymphocytes.","These fragile viruses need close direct contact : saliva (HSV-1, CMV, EBV), respiratory route (VZV, outbreaks in groups), skin lesions (HSV, VZV), sex (HSV-2, CMV), mother to child (during pregnancy: CMV, VZV; at birth: HSV-2; after birth: HSV-1), and transfusion or transplantation (EBV, CMV, HHV-6, HHV-8)."],"dp":[]},"viro1-herpesviruses:e4":{"s":2,"u":["HSV-1: oral, eye, brain. HSV-2: genital, neonatal.","HSV-1 is acquired in childhood (70-95% of adults are seropositive) and causes oral, ocular and cerebral disease; HSV-2 is mainly sexually transmitted (genital herpes) and causes neonatal herpes."],"dp":[]},"viro1-herpesviruses:e5":{"s":2,"u":["HSV encephalitis: temporal, necrotising; emergency (aciclovir).","Severe forms: herpes encephalitis (the first cause of viral encephalitis, acute necrotising and haemorrhagic, usually temporal ; mortality over 70% untreated and heavy sequelae: a therapeutic emergency), keratitis (first infectious cause of blindness in industrialised countries), neonatal herpes (from maternal genital herpes during delivery; the mother is asymptomatic in two thirds of cases) and extensive herpes in the immunocompromised."],"dp":[{"h":"Why doctors start aciclovir before the test result in suspected encephalitis","t":"Untreated HSV encephalitis kills most patients and leaves survivors with severe memory and behaviour problems. Aciclovir is safe, and every hour of delay worsens outcome. So a patient with fever, confusion or seizures, especially with temporal lobe signs, gets intravenous aciclovir straight away, and the CSF PCR result is used afterwards to confirm or stop it."}]},"viro1-herpesviruses:e6":{"s":3,"u":["VZV: chickenpox, then shingles in a dermatome.","Reactivation gives shingles (herpes zoster) in about 15%: a painful vesicular rash in one or adjacent dermatomes , more frequent with age and immunosuppression; ophthalmic zoster involves V1."],"dp":[]},"viro1-herpesviruses:e7":{"s":3,"u":["EBV: mononucleosis; Burkitt lymphoma, nasopharyngeal carcinoma.","It is oncogenic: Burkitt lymphoma (equatorial Africa), nasopharyngeal carcinoma (North Africa, Middle East, South Asia), Hodgkin and non-Hodgkin lymphomas (especially in the immunocompromised), some gastric cancers."],"dp":[]},"viro1-herpesviruses:e8":{"s":4,"u":["Diagnosis by PCR on fresh lesions.","Samples: fresh lesions, as early as possible, before antiseptics , transported fast in transport medium (fragile viruses); 1 day at +4 °C, −80 °C for culture, −20 °C for PCR.","PCR is the diagnostic method."],"dp":[]},"viro1-herpesviruses:e9":{"s":4,"u":["Aciclovir/valaciclovir; ganciclovir for CMV; varicella and shingles vaccines.","Treatment: aciclovir (nucleoside analogue) for HSV; aciclovir or mostly valaciclovir for VZV; foscarnet or cidofovir for aciclovir-resistant virus; ganciclovir , foscarnet or cidofovir for CMV .","Prevention: the varicella vaccine (live attenuated, the first vaccine against a human herpesvirus; 2 doses from 12 months, at least 2 months apart; available as MMRV), the shingles vaccine from age 50 (Zostavax: live; Shingrix: recombinant subunit ), and safer sex for HSV-2."],"dp":[]}},"meta":{"1uhnl6a":{"a":"recall","vg":"viro1-herpesviruses:e0/recall/1"},"1w88sxr":{"a":"recall","vg":"viro1-herpesviruses:e1/recall/1"},"vs9bcm":{"a":"recall","vg":"viro1-herpesviruses:e4/recall/1"},"17zi26n":{"a":"recall","vg":"viro1-herpesviruses:e2/recall/1"},"9p2tna":{"a":"recall","vg":"viro1-herpesviruses:e2/recall/2"},"1z4gfy":{"a":"relationship","vg":"viro1-herpesviruses:e5/relationship/1"},"1a1cf2m":{"a":"recall","vg":"viro1-herpesviruses:e5/recall/1"},"x4b06x":{"a":"recall","vg":"viro1-herpesviruses:e4/recall/2"},"32lhf6":{"a":"relationship","vg":"viro1-herpesviruses:e6/relationship/1"},"1gqsa7k":{"a":"relationship","vg":"viro1-herpesviruses:e7/relationship/1"},"16uwh5d":{"a":"recall","vg":"viro1-herpesviruses:e7/recall/1"},"1mnt4ys":{"a":"recall","vg":"viro1-herpesviruses:e3/recall/1"},"nziyrq":{"a":"recall","vg":"viro1-herpesviruses:e9/recall/1"},"18062nv":{"a":"recall","vg":"viro1-herpesviruses:e9/recall/1"},"t2l5y0":{"a":"recall","vg":"viro1-herpesviruses:e8/recall/1"},"1afcl4y":{"a":"recall","vg":"viro1-herpesviruses:e3/recall/2"}},"explRev":"0dfa083caf18"};
